import { basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';

// The write-surface gate for the improve-comments pass. Its skill bounds every edit
// to comments in code files and to `README.md` documents; the pass runs unattended
// and writes the repo's OWN SOURCE — the one surface no other tidy-repo task
// touches — so the boundary needs a machine guarantee rather than a prose request.
//
// THE PERMISSION IS READ, NEVER ASSERTED. A file passes because its code is
// identical once the comments are stripped from both sides, not because the run
// says it only touched comments. That is the whole point: a run that quietly
// renamed a variable while "improving comments" is exactly what this catches, and
// a run cannot talk its way past a text comparison.
//
// THREE SHAPES FAIL, and each is deliberate rather than an oversight:
//   - a file whose language `commentOnly` cannot parse counts as code, so a comment
//     edit in one reds the run. Answering "I could not look" as a pass would make
//     the gate silently narrower than the languages a repo actually holds;
//   - an ADDED or DELETED code file is never comment-only, whatever it holds — a
//     whole file is a whole file, and this pass does not add or remove them;
//   - a DELETED `README.md` is not an improvement to a README. Modifying one is the
//     pass's business; deciding a document should not exist is not.
//
// RELEVANCE IS THE PINNED COMMIT SUBJECT, the same self-gating shape
// claudinite-growth's capture gate uses: the run marks itself, so this rule can run
// everywhere tidy-repo is active — at the session Stop hook and on every PR — and
// costs ~nothing on a branch that is not this pass.
export const IMPROVE_COMMENTS_RUN = /^Claudinite tidy: improve comments/;

const isReadme = (p) => basename(p).toLowerCase() === 'readme.md';

const rule = {
  id: 'improve-comments-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/tidy-repo/skills/improve-comments/SKILL.md',
  description: 'An improve-comments run changes only comments in code files, and README.md documents',
  why: 'the pass runs unattended against the repo\'s own source, and its whole safety case is that a comment cannot change behaviour — a run that also moved a line has made an unreviewed code change wearing a housekeeping title',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => IMPROVE_COMMENTS_RUN.test(m))) return [];

    const deleted = new Set(work.deleted);
    return [...new Set([...work.changedFiles, ...work.deleted])]
      .filter((p) => (isReadme(p) ? deleted.has(p) : !commentOnly(p, work.readBase(p), work.read(p))))
      .sort()
      .map((p) => finding(rule, isReadme(p)
        ? {
          file: p,
          what: `an improve-comments run deleted ${p} — a README may be improved, never removed`,
          fix: 'restore the file; deciding a document should not exist is a change that gets reviewed, not a comment pass',
        }
        : unparseable(p)
          ? {
            file: p,
            what: `an improve-comments run changed ${p}, whose language the comment parser cannot read`,
            fix: `revert ${p} — outside the parser's set a file counts as code, so nothing here can show the change was only comments; leave them to a change that gets reviewed`,
          }
          : {
            file: p,
            what: work.readBase(p) === null || deleted.has(p)
              ? `an improve-comments run added or deleted ${p}, which is never a comment-only change`
              : `an improve-comments run changed more than the comments in ${p}`,
            fix: 'keep the branch to comment text in code files and to README.md content — a rename, a moved line or a reformat is its own change, with its own review',
          }));
  },
};

// Whether the file's language is one `commentOnly` can parse at all. Only used to
// pick the remedy: a run told "you changed more than comments" about a `.py` file
// it only commented would go looking for a code edit that isn't there.
function unparseable(p) {
  const dot = p.lastIndexOf('.');
  return !COMMENT_CHECKABLE.has(dot === -1 ? '' : p.slice(dot).toLowerCase());
}

export default [rule];

// The baseline pack: cross-project working discipline, the task lifecycle, and
// the general engineering skills. Declared explicitly like every other pack — no pack is active by
// default. Bootstrap's --init seeds the declaration and the nightly update
// backfills it into existing consumers; never fingerprinted (the declaration is
// authoritative — dropping it is a deliberate choice).
//
// Its skills/ holds general engineering practice every project's work can call for,
// whatever its technology, mounted wherever basics is declared (which --init seeds
// everywhere). When one stops being a baseline activity, its directory moves to the
// pack whose projects need it (#385 moved the git/GitHub and Claudinite-lifecycle
// skills out).
export default {
  // A migration record's declared `version` must be ≤ this number, and this number must
  // MOVE for that record to reach a member already at the previous one:
  // `migrationApplies` is `want > have` against the stamped version, and what gets
  // stamped is this manifest's number — so a record declaring a version above it would
  // re-apply every cycle, forever, draining never.
  version: '60830.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'cross-project working discipline, issue-branch-PR lifecycle, repo hygiene, doc/reference integrity and the baseline engineering, testing and debugging skills',
    excludes: 'technology-specific content — its own tech pack; git procedure and GitHub Actions workflow or platform behaviour — git-github',
  },
  seededByDefault: true,
  // `core` is required rather than assumed: this pack is declared everywhere, so
  // the closure is what puts Claudinite's own rules in front of every session, and
  // `barriers` arrives with it. git-github carries the git/GitHub side of the task
  // lifecycle (#385).
  requires: ['claudinite-lifecycle', 'git-github'],
  // Rules that audit the repo as it stands, whatever this session did.
  // warning-suppression and rules-line-length are declared checks in this
  // pack's declared-checks.json, discovered structurally beside these.
  // Rules that judge the change and the session in front of you — the branch's
  // commits, the diff, the conversation. task-lifecycle and squash-merge-history
  // are declared checks carrying scope: "work", discovered structurally beside
  // these.
  // `task-janitor` and `ci-performance` are this pack's scheduled tasks,
  // discovered by the scheduler's filesystem scan (packs/claudinite-tasks/discover.mjs)
  // rather than declared here.
};

// The claudinite-fleet-sheepdog pack: a MARKER + config. Declaring it on a repo makes that repo the
// fleet ENFORCER — the one that covers and maintains every repo under an owner. It's
// opt-in (a dedicated claudinite-fleet-sheepdog repo declares it; NOT seeded by --init).
//
// The pack is thin: prose (RULES.md), the config schema (the pack entry's config =
// { owner, kind, exclude, canonRepo, packSeeds }), and the
// account-spanning sweeps
// that ARE the cross-repo reach the pack adds — each with the ordinary agentless
// scheduled task that runs it (the sweep IS its code-work, and its
// required_secrets is what asks the repo for FLEET_GITHUB_TOKEN):
//
//   tasks/fleet-roster/check-fleet-roster.mjs          is a repo a MEMBER, and is that
//     adoption-issues.mjs + drift-issues.mjs           membership still MEANING anything?
//                                                      (one walk, two issue families)
//   tasks/fleet-add-missing-packs/                     which packs is a member MISSING — the
//     scan-for-needed-packs.mjs + force-add-packs.mjs  ones its SHAPE suspects, or the ones
//                                                      the owner named on a forced run?
//   tasks/fleet-pack-seeds/check-fleet-pack-seeds.mjs  does a member DECLARE what
//                                                      this fleet standardizes on?
//   tasks/fleet-baseline/force-fleet-baseline.mjs      make every member baseline NOW
//                                                      (frequency: manual — the
//                                                      operator's lever, forced only)
//
// Each sweep lives INSIDE its task's folder — nothing outside that task uses it.
// The pack root holds only what they all need: fleet-api.mjs (the cross-repo REST
// primitives), fleet-config.mjs (the one reader of this pack entry's config) and
// fleet-token.mjs (the one statement of what FLEET_GITHUB_TOKEN must be granted).
//
// ROSTER carries two questions rather than one because they are asked of the same
// repos from the same walk (#788): coverage, and — because per-project scheduling made
// every member maintain itself and in doing so removed the last thing that looked at a
// member from the OUTSIDE — whether that coverage still means anything. Self-maintenance
// cannot detect its own absence. Two issue families, one enumeration, one declaration
// read per repo; the split that remains is between the FAMILIES (adoption-issues.mjs,
// drift-issues.mjs), which close on unrelated conditions, and not between two walks that
// could classify the same repo differently.
//
// ADD-MISSING-PACKS exists because a pack's `detect` fingerprint is consulted ONCE, at
// bootstrap's --init: baselining backfills the seeded packs and each declared pack's
// `requires` closure, but never re-fingerprints, so a member that grows into a pack
// after adoption is never told. It is PARAMETERISED (`scan_for_needed_packs`, `repos`,
// `ADD_PACKS`… — no defaults; the weekly declaration sends its own explicitly, a forced
// run sends the rest through the scheduler's override bag) and it runs NO agent here: it
// converges a work-list issue IN each member and fires that member's own scheduler, whose
// adopt-requested-packs task (claudinite-growth) adopts with the repo checked out —
// the fan-out model (#749): the enforcer dispatches, the member executes, and no agent
// anywhere needs cross-repo access.
//
// PACK-SEEDS is the one that WRITES to members: some packs need a parameter no
// member can derive, because the answer is a fact about the FLEET — and only the enforcer
// holds it, because it IS the fleet. It names no pack itself: every id comes from this
// repo's own `packSeeds`.
//
// The pack carries NO workflow of its own: every sweep runs Action-side inside the
// repo's one scheduler workflow, where the secret is already reachable, and the two
// operator levers (fleet-baseline; a forced fleet-add-missing-packs) are `manual` /
// hand-created work items on that same queue — `create-work-item <pack>/<task>`. The
// standalone fleet-baseline workflow this pack once kept in the enforcer's .github/
// (the one file the nightly converge could never push itself, #649) was retired
// 2026-08-11 (#749, packs/claudinite-fleet-sheepdog/migrations/2026-08-11-fleet-baseline-task) along with its
// follow-the-fleet report: dispatching is the enforcer's job, reporting is each
// member's own.
//
// Everything else — the scheduler run, the executor, the task engine (packs/claudinite-tasks/),
// scheduling — is CORE and pack-agnostic; none of it runs, dispatches, or depends on
// these sweeps.
//
// ONE CHECK, and it names no pack (seeds-agree.mjs): the seed sweep writes this
// repo's `packSeeds` into every member without ever consulting what this repo declares
// for the same pack, so the two can drift apart silently. That is a fact about seeding,
// not about any pack seeded — which is why it lives here and not in the pack whose
// config happened to drift.
import { fleetTokenHandoverStep } from './fleet-token.mjs';

export default {
  version: '60830.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'fleet-enforcer duties for the repo watching every other repo — coverage, freshness, standardized packs',
    excludes: 'anything a member does to itself — tidying is tidy-repo, lessons are claudinite-growth; the fleet brief is claudinite-dashboard',
  },
  // Audits the enforcer's config as it stands, whatever this session touched: a seed
  // that drifted in an earlier commit is just as silent as one that drifted in this one.

  // The token is the whole pack's one credential and only a human can mint it. The step
  // is RENDERED from fleet-token.mjs rather than written here, because the failure this
  // exists to prevent is a person granting a subset (#1030): a sweep's own message names
  // what that sweep needs, and five such messages assemble into a grant missing exactly
  // the permission no other sweep exercises. What adoption presents is the union.
  adoptionHandover: [fleetTokenHandoverStep()],
};

// Opt into the growth lifecycle: a repo declaring claudinite-growth contributes its
// hard-won lessons up to the Claudinite canon and prunes them back out once the canon
// owns them. This pack carries the REPO-side stages — extract, dedup, the weekly local
// pack discovery, and the weekly prose-to-checks sweep — as scheduled tasks under this pack's
// own `tasks/`, discovered by the scheduler's filesystem scan
// (packs/claudinite-tasks/discover.mjs), so none of them is declared here. The central
// promote stage — lifting portable lessons up into the shared canon — is a home-only
// duty that runs canon-side, outside this pack; its precondition targets exactly the
// members that declare THIS pack, minus any member whose entry sets config.promote:
// false (the promotion opt-out; extraction and dedup stay local either way).
//
// EXTRACTION IS ONE TASK OVER TWO SOURCES. growth-extract (tasks/growth-extract/)
// runs the extract-from-activity skill over the window's commits/PRs/issues and the
// extract-from-conversations skill over the captured logs, then the prose-to-checks
// skill over the prose it just wrote, and lands all of it in one PR delivered
// per the repo's delivery settings.
// The halves were two tasks firing at the same nightly anchor against the same local
// packs; they shared the bar, the ladder and the dedup surface, so the split bought
// nothing and cost a second opus dispatch, a second PR, and two runs deduping
// against a corpus the other was concurrently writing.
//
// The pack also owns the CONVERSATION lifecycle: capture-log.mjs pushes a session's
// conversation onto the orphan conversation-logs branch (in-session — it needs the
// live transcript), driven by TWO events: merge-to-main's capture step, with the
// issue the merge closed, and session-end.mjs, with --issue 0, invoked by the
// engine's SessionEnd hook runner. The second is best-effort and captures what the
// first structurally cannot — sessions that never merge, and the post-merge tail of
// the ones that do; it is safe to double-write because capture deltas on the session
// id. growth-extract's conversation half then mines those pushed logs on its own
// access model — the logs branch is in the repo, so reading it, committing lessons to
// local packs are plain local git (the logs branch itself is read-only to it); only
// posting the short summary behind each extracted rule on its issue uses the GitHub
// MCP tools. RETENTION IS A SEPARATE, AGENTLESS TASK (tasks/logs-prune/): deleting a
// capture past config.retention_days is arithmetic on dates, and keeping it inside
// the opus run also kept a precondition arm alive whose only job was to dispatch
// that run on a quiet repo. Age is enough because of the extract run's reading
// window — it reads from the oldest end of the branch every run — not because the
// two tasks hand anything to each other.
//
// And it owns the SKILL-USAGE metric the promotion ladder's skill-vs-prose call was
// missing: usage-fold (tasks/usage-fold/) counts skill loads and their activity
// denominators out of those same captured logs into a small tracked aggregate.
// Fleet-wide aggregation is NOT here — the canon knows mechanisms, never repos; that
// is the claudinite-fleet-sheepdog pack's job, in the fleet-enforcer repo.
//
// ADOPTION IS NOT HERE. `adopt-claudinite`, `adopt-pack` and the
// adopt-requested-packs task were bundled in this pack for want of a better home;
// their subject is Claudinite's own surface, so they moved to the `core` pack.
//
// rule-revalidation (tasks/rule-revalidation/) covers the failure mode the other
// stages structurally cannot see: a rule that was right, and whose ENVIRONMENT
// moved. A claim about the harness, a token's reach or an MCP tool's existence is
// falsified by a platform this repo does not control, and nothing here goes red
// when it happens — so the trigger is the calendar, and the method is re-running
// the probe rather than re-reading the prose. It shares prose-to-checks-sweep's
// `pack_paths` config: a member revalidates its own local packs, the canon its own.
//
// growth-discover-packs is the weekly LOCAL pack-discovery reflection: the repo
// manifests its own stack, notices project-specific knowledge no canon pack homes,
// and authors a local pack for it under its own `.claudinite/local/packs/`.
//
// A declared pack (no fingerprint), seeded like tidy-repo: --init seeds it into every
// new repo, the one-time grow-with-claudinite-seed migration seeds the existing fleet,
// and baselining never re-adds it — so removing it is a durable opt-out.
//
// No adoption question over config.retention_days — the value stays unset (hidden)
// by default, which is fail-safe (capture-only, the prune deletes nothing) rather
// than something every adopter must weigh in on. A project that wants the prune
// active sets retention_days itself.
export default {
  version: '60830.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'authoring Claudinite content here — lesson extraction, dedup, revalidation, conversation logs, skill-usage folding, the task contract',
    excludes: 'this repo\'s Claudinite status — mount, declaration, adoption, update — claudinite-lifecycle; issue/PR housekeeping — tidy-repo; fleet sweeps — claudinite-fleet-sheepdog',
  },
  seededByDefault: true,
  // Growth builds on Claudinite's own surface — a lesson is routed by reading the
  // pack catalog and landed by adopting or authoring a pack — so `core` is a
  // prerequisite rather than an ambient assumption.
  requires: ['claudinite-lifecycle'],
  // The task contract (the writing-tasks skill). Relevance-first — inert until
  // the repo carries a tasks/<name>/task.mjs of its own — and here rather than in
  // claudinite-lifecycle because these judge whether a task is WRITTEN correctly,
  // which is authoring, not whether Claudinite is working in this repo. The
  // contract's third rule (task-phase-discipline) is a declared check in this pack's
  // declared-checks.json, beside them.
};

// Claudinite's own surface in a repo that runs it: the vendored mount, the
// declaration that activates a pack, adopting Claudinite and adopting a pack.
//
// EVERY RULE HERE JUDGES A MEMBER'S CLAUDINITE STATUS — is this repo declared,
// converged, gated and scheduled such that Claudinite works in it. Rules about
// how the canon's own content is maintained are not this pack's, however much
// they look like it.
//
// MANDATORY. `basics` requires this pack, which both vendors its content and
// materializes its declaration wherever a declaration is written; the
// migrations/2026-08-14-core-seed record declares it into members that already
// exist. Both run outside any check — activation reads the literal declaration,
// so `claudinite-lifecycle-declared` reports a member that has lost the entry rather
// than being what puts it there.
export default {
  version: '60830.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'using Claudinite itself — the vendored mount, the pack declaration, bootstrapping, adopting packs, the self-refresh update',
    excludes: 'working discipline and the task lifecycle — basics; authoring Claudinite content, scheduled tasks included — claudinite-growth; git — git-github',
  },
  seededByDefault: true,
  // The consumer-isolation wall (claudinite-isolation) is a declared check — a
  // forbidReferences entry in this pack's declared-checks.json, run by the
  // engine's reference-scanning like any barrier. The barriers pack stays
  // required for the per-repo config rule members' own edges ride.
  requires: ['barriers'],
  // Both scheduled tasks live in this pack's `tasks/`, discovered by the
  // scheduler's filesystem scan (packs/claudinite-tasks/discover.mjs) rather than
  // declared here: `update`, the per-repo self-refresh every member runs, and
  // `adopt-requested-packs`, which acts on a repo's pack-adoption requests.
  //
  // `update` being HERE is what `claudinite-lifecycle-declared` is blocking for. A member runs it
  // from its vendored copy and discovery finds only a literally-declared pack's
  // tasks, so a repo that loses this pack's entry loses its self-refresh — and
  // nothing is left that could deliver it one.
};

