348	// THE WRITER-FACING PROSE. A brief is read by an agent at run time and is the only
349	// thing telling it what to write, so a brief still naming the retired pair asks for
350	// a torn state the janitor then repairs. Scanned from the tracked tree rather than a
351	// list, so a new brief is covered the moment it is added.
352	//
353	// Three exclusions, each because the legacy spelling is the point there:
354	//   - `executor.md`, the RETIRED slot mechanism's instructions, frozen for routines
355	//     nobody has repointed — its vocabulary is that scheme's, not this one's;
356	//   - every `VERSIONS.md`, a historical record of what each version did;
357	//   - the sim's scenario-coverage README, whose rows name DESIGN's legacy table.
358	const PROSE_EXCLUDED = /(^|\/)(VERSIONS\.md$|executor\.md$|test\/sim\/README\.md$)/;
359	const trackedProse = (pattern) => execFileSync('git', ['ls-files', pattern], { encoding: 'utf8' })
360	  .split('\n').filter((p) => p && !PROSE_EXCLUDED.test(p));
361	
362	test('no pack brief tells a writer to spell a status the way nothing writes it', () => {
363	  // The bare park as a code span — `on_interrupt: 'needs-human'` is a declaration
364	  // value rather than a label, and does not match.
365	  const retired = [`\`${NEEDS_HUMAN}\``, ...[LEGACY_BLOCKED, LEGACY_READY, LEGACY_EXECUTING,
366	    LEGACY_AGENT, LEGACY_TASK_DONE, LEGACY_TASK_OBSOLETE, ORIGIN_SCHEDULE].flatMap((l) => [`\`${l}\``, `${l} `]),
367	  `\`task:needs-human-`];
368	  const offences = [];
369	  for (const path of trackedProse('packs/**/*.md')) {
370	    const text = readFileSync(path, 'utf8');
371	    for (const spelling of retired) if (text.includes(spelling)) offences.push(`${path}: ${spelling.trim()}`);
372	  }
373	  assert.deepEqual(offences, [], `these briefs name a spelling nothing writes:\n${offences.join('\n')}`);
374	});
375	
376	// A check's `fix` line is the sentence the agent acts on, so it states today's
377	// vocabulary for the same reason a brief does.
378	test('no check catalog remedy names a status nothing writes', () => {
379	  // The agent-facing fields, wherever they sit in a catalog's nesting.
380	  const remedies = (node, out = []) => {
381	    if (Array.isArray(node)) node.forEach((n) => remedies(n, out));
382	    else if (node && typeof node === 'object') {
383	      for (const [key, value] of Object.entries(node)) {
384	        if (typeof value === 'string' && ['fix', 'failureMessage', 'what'].includes(key)) out.push([key, value]);
385	        else remedies(value, out);
386	      }
387	    }
388	    return out;
389	  };
390	  const offences = [];
391	  for (const path of trackedProse('packs/*/declared-checks.json')) {
392	    for (const [field, text] of remedies(JSON.parse(readFileSync(path, 'utf8')))) {
393	      for (const legacy of [LEGACY_BLOCKED, LEGACY_READY, LEGACY_EXECUTING, LEGACY_AGENT,
394	        LEGACY_TASK_DONE, LEGACY_TASK_OBSOLETE, ORIGIN_SCHEDULE, NEEDS_HUMAN]) {
395	        if (new RegExp(`(^|[^:\\w-])${legacy}([^-\\w]|$)`).test(text)) offences.push(`${path} ${field}: ${legacy}`);
396	      }
397	    }
398	  }
399	  assert.deepEqual(offences, [], `these remedies name a spelling nothing writes:\n${offences.join('\n')}`);
400	});
401

