// THE LABEL VOCABULARY'S DECODE (tasks-dispatch DESIGN §4; the migration of #1119).
// Labels are stored data: an open item wears whatever the engine that filed it
// wrote, and a member converges on its own schedule. So every reader decodes, and
// what these tests pin is that ONE pass maps every spelling ever written straight
// to today's — plus the two places that would silently strand a member if they
// disagreed: the ensure-list (a label that does not exist 422s the write that
// applies it) and the executor workflow's literal event trigger.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN,
  LEGACY_BLOCKED, LEGACY_READY, LEGACY_EXECUTING, LEGACY_AGENT,
  LEGACY_TASK_DONE, LEGACY_TASK_OBSOLETE,
  TASK_DONE, TASK_OBSOLETE, OUTCOME_DONE, OUTCOME_OBSOLETE, OUTCOME_DELIVERED,
  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
  STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_DECISION,
  STATUS_NEEDS_HUMAN_FAILURE, STATUS_DONE, STATUS_REJECTED,
  STATUS_LABELS, ORIGIN_LABELS, ORIGIN_PLANNED, ORIGIN_AD_HOC, ORIGIN_GITHUB, ORIGIN_SCHEDULE,
  QUEUE_LABELS, statusOf, statusesOn, isStatus, isParked, parkKindOf, originOf,
  spellingsOf, isBlockingPark, outcomeOf, triageLabelFor, TRIAGE_LABELS, requeueHint,
} from '../../queue/work-item.mjs';
import { swapStatus, clearStatus } from '../../queue/apply-status.mjs';
import { FAILURE_LABELS } from '../../queue/workflow-failure.mjs';

const item = (...labels) => ({ number: 1, title: '[claudinite-work] basics/task-janitor', state: 'open', labels });

// DESIGN §4's legacy table, in full — the left column is every spelling any fielded
// engine has written, the right is what a reader must see today.
test('every legacy spelling decodes straight to its canonical status', () => {
  for (const [legacy, canonical] of [
    [LEGACY_BLOCKED, STATUS_BLOCKED],
    [LEGACY_READY, STATUS_READY],
    [LEGACY_EXECUTING, STATUS_RUNNING_EXECUTOR],
    [LEGACY_AGENT, STATUS_RUNNING_AGENT],
    [LEGACY_TASK_DONE, STATUS_DONE], [OUTCOME_DONE, STATUS_DONE],
    [LEGACY_TASK_OBSOLETE, STATUS_REJECTED], [OUTCOME_OBSOLETE, STATUS_REJECTED],
  ]) {
    assert.equal(statusOf(item(legacy)), canonical, `${legacy} should read as ${canonical}`);
  }
});

test('a canonical status reads as itself', () => {
  for (const status of STATUS_LABELS) assert.equal(statusOf(item(status)), status);
});

// The legacy park is a PAIR, and the sub-label is what decides the kind.
test('the legacy park pair decodes to the kind its sub-label names', () => {
  for (const [sub, canonical] of [
    [NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_ACTION],
    [NEEDS_HUMAN_DECISION, STATUS_NEEDS_HUMAN_DECISION],
    [NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_APPROVAL],
    [NEEDS_HUMAN_FAILURE, STATUS_NEEDS_HUMAN_FAILURE],
  ]) {
    assert.equal(statusOf(item(NEEDS_HUMAN, sub)), canonical);
    assert.equal(parkKindOf(item(NEEDS_HUMAN, sub)), canonical.split('needs-human-')[1]);
  }
});

// The compatibility direction the design chooses deliberately, in both directions:
// an OLDER engine's bare park, and a NEWER engine's kind word this one never heard
// of, both hold the lane rather than letting a broken task keep filing work.
test('a park whose kind cannot be decoded reads as failure, and only failure holds the lane', () => {
  assert.equal(statusOf(item(NEEDS_HUMAN)), STATUS_NEEDS_HUMAN_FAILURE);
  assert.equal(statusOf(item('task:needs-human-quantum')), STATUS_NEEDS_HUMAN_FAILURE);
  assert.equal(statusOf(item('task:status:needs-human-quantum')), STATUS_NEEDS_HUMAN_FAILURE);

  assert.equal(isBlockingPark(item(NEEDS_HUMAN)), true);
  assert.equal(isBlockingPark(item(STATUS_NEEDS_HUMAN_FAILURE)), true);
  for (const soft of [STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_DECISION, STATUS_NEEDS_HUMAN_APPROVAL]) {
    assert.equal(isBlockingPark(item(soft)), false, `${soft} is somebody's inbox, not a fault`);
  }
  assert.equal(isBlockingPark(item(NEEDS_HUMAN, NEEDS_HUMAN_APPROVAL)), false);
  assert.equal(isBlockingPark(item(STATUS_READY)), false);
});

// A torn transition can leave a state label beside a park. The queue must read that
// as PARKED — reading it as ready would hand an executor an item a human owns.
test('a park outranks any state label standing beside it', () => {
  assert.equal(statusOf(item(READY, NEEDS_HUMAN, NEEDS_HUMAN_ACTION)), STATUS_NEEDS_HUMAN_ACTION);
  assert.equal(isStatus(item(READY, NEEDS_HUMAN), STATUS_READY), false);
  assert.equal(isParked(item(STATUS_RUNNING_AGENT, STATUS_NEEDS_HUMAN_DECISION)), true);
});

// MID-FLIP, the case the whole two-spelling period turns on: an item filed by the
// old engine and touched by the new one wears both spellings of ONE status. It is
// not torn, and a reader that counted labels rather than statuses would say it was.
test('an item wearing both spellings of one status reads as that one status', () => {
  assert.deepEqual(statusesOn(item(READY, STATUS_READY)), [STATUS_READY]);
  assert.equal(statusOf(item(READY, STATUS_READY)), STATUS_READY);
  assert.deepEqual(statusesOn(item(READY, EXECUTING)).sort(), [STATUS_RUNNING_EXECUTOR, STATUS_READY].sort());
});

test('an item wearing nothing the vocabulary knows has no status at all', () => {
  assert.equal(statusOf(item()), null);
  assert.equal(statusOf(item('area:docs', ORIGIN_SCHEDULE)), null);
  assert.equal(isParked(item()), false);
  assert.equal(parkKindOf(item(STATUS_READY)), null);
});

// The origin is read, never inferred. `origin:schedule` is inert stored data: an
// older engine wrote it, nothing writes it now, and reading it as an origin would
// put a marker nothing maintains back into play.
test('the origin is whichever `task:origin:` label stands, and the retired marker is not one', () => {
  assert.equal(originOf(item(STATUS_READY, ORIGIN_PLANNED)), ORIGIN_PLANNED);
  assert.equal(originOf(item(ORIGIN_AD_HOC)), ORIGIN_AD_HOC);
  assert.equal(originOf(item(ORIGIN_GITHUB)), ORIGIN_GITHUB);
  assert.equal(originOf(item(ORIGIN_SCHEDULE)), null);
  assert.equal(originOf(item(STATUS_READY)), null);
});

// A closed item's terminal write is its outcome whatever else stands on it, in
// every spelling — the fleet's history is what these numbers are counted from.
test('outcomes decode from every spelling, canonical and legacy alike', () => {
  for (const l of [TASK_DONE, OUTCOME_DONE, STATUS_DONE]) assert.equal(outcomeOf(item(l)), 'done');
  for (const l of [TASK_OBSOLETE, OUTCOME_OBSOLETE, STATUS_REJECTED]) assert.equal(outcomeOf(item(l)), 'obsolete');
  assert.equal(outcomeOf(item(OUTCOME_DELIVERED)), 'delivered');
  assert.equal(outcomeOf(item(AGENT, OUTCOME_DONE, NEEDS_HUMAN)), 'done');
  assert.equal(outcomeOf(item(STATUS_READY)), null);
});

// What a transition has to clear. The item may wear any engine's spelling, so a
// swap that named one would leave the other standing — two live statuses, which is
// the torn state the janitor exists to repair.
test('every spelling of a status is what leaving it clears', () => {
  assert.deepEqual(spellingsOf(STATUS_READY).sort(), [LEGACY_READY, STATUS_READY].sort());
  assert.deepEqual(spellingsOf(STATUS_DONE).sort(), [LEGACY_TASK_DONE, OUTCOME_DONE, STATUS_DONE].sort());
  // Leaving a park leaves it entirely: every kind, both shapes, and the bare label.
  const park = spellingsOf(STATUS_NEEDS_HUMAN_APPROVAL);
  for (const l of [NEEDS_HUMAN, NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION,
    NEEDS_HUMAN_FAILURE, STATUS_NEEDS_HUMAN_FAILURE, STATUS_NEEDS_HUMAN_APPROVAL]) {
    assert.ok(park.includes(l), `a re-queue must clear ${l}`);
  }
});

test('a swap removes both spellings of the status it leaves and adds the one it writes', async () => {
  const removed = []; const added = [];
  const api = {
    removeLabel: async (_gh, _repo, _n, name) => removed.push(name),
    addLabel: async (_gh, _repo, _n, name) => added.push(name),
  };
  await swapStatus(api, null, 'o/r', item(LEGACY_READY), STATUS_READY, EXECUTING);
  assert.deepEqual(removed.sort(), [LEGACY_READY, STATUS_READY].sort());
  assert.deepEqual(added, [EXECUTING]);

  removed.length = 0;
  await clearStatus(api, null, 'o/r', item(STATUS_RUNNING_AGENT), STATUS_RUNNING_AGENT);
  assert.deepEqual(removed.sort(), [LEGACY_AGENT, STATUS_RUNNING_AGENT].sort());
});

// GitHub 422s an attempt to apply a label that does not exist and never creates one
// on demand, so the ensure pass has to know a spelling BEFORE anything writes it —
// and the ensure pass and the flip that starts writing them reach a member in
// separate converges.
test('the ensure-list carries every canonical status and origin, ahead of any writer', () => {
  const ensured = new Set(QUEUE_LABELS.map((l) => l.name));
  for (const name of [...STATUS_LABELS, ...ORIGIN_LABELS]) {
    assert.ok(ensured.has(name), `${name} must be ensured or the write that applies it 422s`);
  }
  // And the legacy spellings stay ensured: nothing writes them, but open items wear
  // them and deleting a label strips it from every issue that carries it.
  for (const name of [LEGACY_BLOCKED, LEGACY_READY, LEGACY_EXECUTING, LEGACY_AGENT,
    NEEDS_HUMAN, LEGACY_TASK_DONE, LEGACY_TASK_OBSOLETE, OUTCOME_DELIVERED]) {
    assert.ok(ensured.has(name), `${name} is worn by open items, so it must stay ensured`);
  }
});

// A workflow's event trigger names label strings LITERALLY — nothing there decodes
// — so this is the one surface where both vocabularies must appear at once. Read
// from the real files, both copies: the stub every member is given, and the canon's
// own hand-maintained copy, which no converge writes.
test('the executor triggers on both ready spellings, in the stub and in the canon\'s own copy', () => {
  for (const path of ['packs/claudinite-tasks/stubs/claudinite-executor.yml', '.github/workflows/claudinite-executor.yml']) {
    const yml = readFileSync(path, 'utf8');
    for (const spelling of [STATUS_READY, READY, 'task:urgent']) {
      assert.ok(yml.includes(`github.event.label.name == '${spelling}'`), `${path} must trigger on ${spelling}`);
    }
  }
});

// A workflow reporting its own failure has an origin like anything else, and it is
// a break to diagnose — the one park lane that holds the task's lane.
test('a workflow-failure issue is filed with its origin and its park', () => {
  const names = FAILURE_LABELS.map((l) => l.name);
  for (const label of [ORIGIN_GITHUB, STATUS_NEEDS_HUMAN_FAILURE]) {
    assert.ok(names.includes(label), `a failure issue must be labelled ${label}`);
  }
  // Ensured, not merely applied: GitHub 422s the write that applies an unknown
  // label, and a first-run failure may precede any other label-ensure.
  for (const { name, color, description } of FAILURE_LABELS) {
    assert.ok(name && color && description, `${name} must be ensured to spec, not applied bare`);
  }
});

// --- what the decode is FOR: the machinery reacting to either spelling ---------
// The unit tests above pin the map. These pin the consequence — that an item filed
// in canonical spellings is picked up, reclaimed, escalated and repaired exactly as
// one filed in legacy spellings is, which is the whole promise of the migration
// running with fielded engines still writing the old words.

import { pickOrder } from '../../queue/executor.mjs';
import { planSchedulerRun } from '../../queue/scheduler-run.mjs';
import { staleReadyItems, deadAgentItems, statelessItems } from '../../queue/janitor-rules.mjs';
import { isReleasable } from '../../queue/readiness.mjs';

const workItem = (n, labels, extra = {}) => ({
  number: n, title: '[claudinite-work] p/daily1', state: 'open', body: 'packs/p/tasks/daily1/task.md\n',
  created_at: '2026-08-14T04:10:00Z', updated_at: '2026-08-14T04:15:00Z', labels, ...extra,
});

test('the executor picks up an item readied in either spelling, and yields to a running twin in either', () => {
  assert.deepEqual(pickOrder([workItem(1, [READY]), workItem(2, [STATUS_READY])]).map((i) => i.number).sort(), [1, 2]);
  // The same-title mutex: one task, one execution at a time, and the running twin
  // is recognised whichever engine wrote its label.
  assert.deepEqual(pickOrder([workItem(1, [STATUS_READY]), workItem(2, [EXECUTING])]), []);
  assert.deepEqual(pickOrder([workItem(1, [READY]), workItem(2, [STATUS_RUNNING_AGENT])]), []);
  // A DIFFERENT title is a different run, so it is pickable beside either.
  const other = { ...workItem(3, [STATUS_RUNNING_EXECUTOR]), title: '[claudinite-work] p/daily2' };
  assert.deepEqual(pickOrder([workItem(1, [READY]), other]).map((i) => i.number), [1]);
  // And a parked item is never picked, in either shape.
  assert.deepEqual(pickOrder([workItem(1, [STATUS_NEEDS_HUMAN_FAILURE]), workItem(2, [READY, NEEDS_HUMAN])]), []);
});

test('the scheduler run reclaims a dead claim written in either spelling', async () => {
  const tasks = [{ pack: 'p', id: 'daily1', taskPath: 'packs/p/tasks/daily1/task.md', decl: { id: 'daily1', frequency: 'daily' } }];
  for (const label of [EXECUTING, STATUS_RUNNING_EXECUTOR]) {
    const { ops } = await planSchedulerRun({
      tasks, items: [workItem(1, [label])], now: '2026-08-14T05:30:00Z',
      schedule: { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 },
    });
    assert.equal(ops.filter((o) => o.kind === 'reclaim').length, 1, `${label} should be reclaimable`);
  }
});

test('the janitor\'s rules read either spelling', () => {
  const late = '2026-08-20T00:00:00Z';
  for (const label of [READY, STATUS_READY]) {
    assert.equal(staleReadyItems([workItem(1, [label])], late).length, 1, `${label} should go stale`);
  }
  for (const label of [AGENT, STATUS_RUNNING_AGENT]) {
    assert.equal(deadAgentItems([workItem(1, [label])], late).length, 1, `${label} should hit the leash`);
  }
  // A park is nobody's to escalate again, whichever shape it wears.
  assert.equal(staleReadyItems([workItem(1, [READY, NEEDS_HUMAN])], late).length, 0);
  assert.equal(deadAgentItems([workItem(1, [STATUS_NEEDS_HUMAN_DECISION])], late).length, 0);
  // Rule D reads the absence of a status, so an item wearing only an origin — or
  // only the retired schedule marker — is the torn-swap leaving it is meant to find.
  assert.deepEqual(statelessItems([workItem(1, [ORIGIN_PLANNED]), workItem(2, [STATUS_BLOCKED])]).map((i) => i.number), [1]);
});

test('a blocked item is releasable in either spelling, and a parked one never is', () => {
  const body = 'packs/p/tasks/daily1/task.md\n\nBlocked-by: #7\n';
  for (const label of [BLOCKED, STATUS_BLOCKED]) {
    assert.equal(isReleasable(workItem(1, [label], { body }), { stateOf: () => 'closed' }), true, label);
  }
  assert.equal(isReleasable(workItem(1, [STATUS_BLOCKED, NEEDS_HUMAN], { body }), { stateOf: () => 'closed' }), false);
});

// --- a marked issue's identity -------------------------------------------------
// Its title is the person's own, so everything that used to read the task off the
// title reads it off the worker path the machine block names instead. What this
// pins is that the parse covers both homes a task can have, and that the janitor
// rule which would otherwise skip every request run does not.

import { taskIdFromPath, withMachineBlock } from '../../queue/work-item.mjs';
import { staleReadyComment } from '../../queue/janitor-rules.mjs';
import { LEGACY_BUILT_IN_TASK_PATH, LEGACY_BUILT_IN_TASK_PATH_MOUNTED } from '../legacy-protocol.mjs';

test('a worker path names its task, in both homes and under either root', () => {
  assert.deepEqual(taskIdFromPath('packs/basics/tasks/task-janitor/task.md'), { pack: 'basics', task: 'task-janitor' });
  assert.deepEqual(taskIdFromPath('.claudinite/shared/packs/basics/tasks/task-janitor/task.md'), { pack: 'basics', task: 'task-janitor' });
  assert.deepEqual(taskIdFromPath(LEGACY_BUILT_IN_TASK_PATH), { pack: 'engine', task: 'implement-request' });
  assert.deepEqual(taskIdFromPath(LEGACY_BUILT_IN_TASK_PATH_MOUNTED), { pack: 'engine', task: 'implement-request' });
  assert.equal(taskIdFromPath('please do the thing'), null);
  assert.equal(taskIdFromPath(null), null);
});

// The built-in's home moved with the surface (#1317), and the path a NEW item carries
// is derived from where the module actually sits — so the pack's own `queue/tasks/`
// root has to decode as well as the engine's did. It is the same task under the same
// wire id: the fallback exists for a MARKED ISSUE, whose title is the person's own
// words and carries no id, so a path that fails to decode leaves every new request
// unattributable to the janitor, uncounted by usage-fold, and blank on the dashboard —
// with nothing going red anywhere.
test('the built-in task decodes from its new home as well as its legacy one', async () => {
  const { requestTaskPath } = await import('../../built-in-tasks.mjs');
  for (const path of [
    'packs/claudinite-tasks/queue/tasks/implement-request/task.md',
    '.claudinite/shared/packs/claudinite-tasks/queue/tasks/implement-request/task.md',
  ]) assert.deepEqual(taskIdFromPath(path), { pack: 'engine', task: 'implement-request' }, path);

  // …and the path the code actually mints is one of them, rather than a third shape
  // this test happens to spell correctly.
  const CANON = join(dirname(fileURLToPath(import.meta.url)), '../../../..');
  assert.deepEqual(taskIdFromPath(requestTaskPath(CANON)), { pack: 'engine', task: 'implement-request' },
    `the minted path ${requestTaskPath(CANON)} must decode`);
});

test('a marked issue that nobody picks up still goes stale', () => {
  const marked = {
    number: 9, title: 'A thing to do', state: 'open', labels: [STATUS_READY, ORIGIN_AD_HOC],
    created_at: '2026-08-14T04:10:00Z', updated_at: '2026-08-14T04:10:00Z',
    body: withMachineBlock('Do it.\n', `${LEGACY_BUILT_IN_TASK_PATH}\n\nRequest: #9`),
  };
  assert.deepEqual(staleReadyItems([marked], '2026-08-20T00:00:00Z').map((i) => i.number), [9]);
  assert.match(staleReadyComment(marked), /engine\/implement-request/);
});

// --- the write side, after the flip --------------------------------------------
// The read side above says every spelling is understood. This says which one is
// WRITTEN — the half a member sees on its issues, and the half that has to move
// exactly once for the fleet to converge on one vocabulary (#1119).

test('the engine writes canonical spellings, and only canonical spellings', () => {
  for (const [name, value] of [
    ['BLOCKED', BLOCKED], ['READY', READY], ['EXECUTING', EXECUTING], ['AGENT', AGENT],
    ['TASK_DONE', TASK_DONE], ['TASK_OBSOLETE', TASK_OBSOLETE],
    ['NEEDS_HUMAN_ACTION', NEEDS_HUMAN_ACTION], ['NEEDS_HUMAN_DECISION', NEEDS_HUMAN_DECISION],
    ['NEEDS_HUMAN_APPROVAL', NEEDS_HUMAN_APPROVAL], ['NEEDS_HUMAN_FAILURE', NEEDS_HUMAN_FAILURE],
  ]) {
    assert.ok(STATUS_LABELS.includes(value), `${name} must be a canonical status, got ${value}`);
  }
  // The names survive the flip because fielded pack versions import them — a pack on
  // the old engine writes a legacy label, which every decoder here still reads.
  assert.notEqual(BLOCKED, LEGACY_BLOCKED);
  assert.equal(statusOf(item(LEGACY_BLOCKED)), BLOCKED);
});

test('a park is one label, and a kind word resolves to it', () => {
  for (const kind of ['action', 'decision', 'approval', 'failure']) {
    assert.equal(triageLabelFor(kind), `task:status:needs-human-${kind}`);
  }
  // A worker that misspells its class has a bug, which is exactly what that lane means.
  assert.equal(triageLabelFor('quantum'), STATUS_NEEDS_HUMAN_FAILURE);
  // And nothing writes the bare legacy park any more, though everything reads it.
  assert.equal(TRIAGE_LABELS.every((l) => l.startsWith('task:status:needs-human-')), true);
});

test('the re-queue lever is stated in one place, and it is clearing the status', () => {
  assert.match(requeueHint, /clear its status label/);
  assert.match(requeueHint, new RegExp(STATUS_READY.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')));
});

// THE WRITER-FACING PROSE. A brief is read by an agent at run time and is the only
// thing telling it what to write, so a brief still naming the retired pair asks for
// a torn state the janitor then repairs. Scanned from the tracked tree rather than a
// list, so a new brief is covered the moment it is added.
//
// Three exclusions, each because the legacy spelling is the point there:
//   - `executor.md`, the RETIRED slot mechanism's instructions, frozen for routines
//     nobody has repointed — its vocabulary is that scheme's, not this one's;
//   - every `VERSIONS.md`, a historical record of what each version did;
//   - the sim's scenario-coverage README, whose rows name DESIGN's legacy table.
const PROSE_EXCLUDED = /(^|\/)(VERSIONS\.md$|executor\.md$|test\/sim\/README\.md$)/;
const trackedProse = (pattern) => execFileSync('git', ['ls-files', pattern], { encoding: 'utf8' })
  .split('\n').filter((p) => p && !PROSE_EXCLUDED.test(p));

test('no pack brief tells a writer to spell a status the way nothing writes it', () => {
  // The bare park as a code span — `on_interrupt: 'needs-human'` is a declaration
  // value rather than a label, and does not match.
  const retired = [`\`${NEEDS_HUMAN}\``, ...[LEGACY_BLOCKED, LEGACY_READY, LEGACY_EXECUTING,
    LEGACY_AGENT, LEGACY_TASK_DONE, LEGACY_TASK_OBSOLETE, ORIGIN_SCHEDULE].flatMap((l) => [`\`${l}\``, `${l} `]),
  `\`task:needs-human-`];
  const offences = [];
  for (const path of trackedProse('packs/**/*.md')) {
    const text = readFileSync(path, 'utf8');
    for (const spelling of retired) if (text.includes(spelling)) offences.push(`${path}: ${spelling.trim()}`);
  }
  assert.deepEqual(offences, [], `these briefs name a spelling nothing writes:\n${offences.join('\n')}`);
});

// A check's `fix` line is the sentence the agent acts on, so it states today's
// vocabulary for the same reason a brief does.
test('no check catalog remedy names a status nothing writes', () => {
  // The agent-facing fields, wherever they sit in a catalog's nesting.
  const remedies = (node, out = []) => {
    if (Array.isArray(node)) node.forEach((n) => remedies(n, out));
    else if (node && typeof node === 'object') {
      for (const [key, value] of Object.entries(node)) {
        if (typeof value === 'string' && ['fix', 'failureMessage', 'what'].includes(key)) out.push([key, value]);
        else remedies(value, out);
      }
    }
    return out;
  };
  const offences = [];
  for (const path of trackedProse('packs/*/declared-checks.json')) {
    for (const [field, text] of remedies(JSON.parse(readFileSync(path, 'utf8')))) {
      for (const legacy of [LEGACY_BLOCKED, LEGACY_READY, LEGACY_EXECUTING, LEGACY_AGENT,
        LEGACY_TASK_DONE, LEGACY_TASK_OBSOLETE, ORIGIN_SCHEDULE, NEEDS_HUMAN]) {
        if (new RegExp(`(^|[^:\\w-])${legacy}([^-\\w]|$)`).test(text)) offences.push(`${path} ${field}: ${legacy}`);
      }
    }
  }
  assert.deepEqual(offences, [], `these remedies name a spelling nothing writes:\n${offences.join('\n')}`);
});

// claudinite-dashboard — a browser view of what a repo's (or a fleet's) Claudinite
// scheduler is doing, published as a static site.
//
// WHY A PACK AND NOT ENGINE CODE. The dashboard is not part of running the scheduler:
// nothing converges, scheduler runs or executes because it exists, and a member that never
// looks at it should not carry it. Engine code is what every member runs; this is
// content a member OPTS INTO, and adoptable content in this corpus is a pack. That
// also buys it the things a pack has and engine code does not — its own version and
// migration lane, a declaration that gates it, and an adoption moment at which its
// deployment can be wired.
//
// WHAT IT READS. Only the queue's own vocabulary and the task declarations at HEAD,
// through the tasks pack's published `shared-code/`, so the page cannot drift from the
// mechanism it renders. Those relative paths resolve identically in the canon (`packs/<id>/`
// beside its siblings) and in a member's mount (`.claudinite/shared/packs/<id>/`), which is
// why the pack can be read straight out of the mount with nothing rewritten.
//
// NO PROSE. There is no way to write the dashboard wrongly in a consuming repo — it is
// a page, not a practice — and prose here would cost every session in every declaring
// repo tokens for something no session acts on. Its README carries the explanation
// instead and `prose` stays null.
//
// PACKS CONTRIBUTE TO THIS PAGE, as data and never as code. A pack ships a descriptor
// (`packs/<id>/dashboard.json`, found by path convention — nothing registers it) naming
// what it has to say; its values come either from its own generated file in the
// member's tree or from one of the two platform facts the page already reads for every
// member. `descriptor-usable`, this pack's one check, holds a descriptor to what the
// page's OWN reader accepts, which the JSON Schema beside it structurally cannot,
// because the failure is silent — a rejected descriptor renders as one apologetic line
// in someone else's browser and nothing goes red where the author is looking.
//
// PUBLISHING IS THE ADOPTION MOMENT. `.github/workflows/` is the one directory the
// nightly update can never push to (the Action's `GITHUB_TOKEN` is refused there), so
// a deploy workflow can only arrive by being SEEDED — written by the install flow and
// committed by the adopting session, which holds a credential the Action does not.
// Hence the `seedOps` entry: adopting the pack is what wires the Pages deploy, and
// the workflow is the member's from the moment it lands.
//
// THE BUILD SCRIPT DELIBERATELY IS NOT SEEDED. `build-site.mjs` lives in the pack and
// is read out of the mount by the seeded workflow, exactly as the scheduler stub reads
// the engine's scheduler run. So the assembly logic keeps converging with the canon while the
// workflow — the part that cannot converge — stays a one-time seed. Only the file that
// has to be frozen is frozen.

export default {
  version: '60827.2',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'the browser dashboard over Claudinite scheduler state and the site that publishes it',
    excludes: 'how the scheduler behaves — core; workflow practice — git-github; product sites — static-website',
  },

  // Never fingerprinted. Nothing in a repo's shape implies wanting a dashboard, and a
  // scan that suspected one from the presence of a scheduler would suspect it in every
  // member on the fleet.
  seededByDefault: false,

  // The page renders the queue's state, so it reads the queue's own vocabulary and
  // anchor math out of the tasks pack's published `shared-code/` — the one sanctioned
  // cross-pack import in the corpus. Declaring the dependency is what puts that pack
  // in a mount that carries this one.
  requires: ['claudinite-tasks'],

  // A page, not a practice — see the header.

  // ONE question, and it is the one thing this pack cannot pick for a repo: which
  // dashboard the deployment is. Everything else has a default that is right for nearly
  // every project — a pasted token, no canon reference — and is read
  // as optional throughout, an unset key meaning the default rather than a
  // misconfiguration. The mode is not like that: both answers are ordinary, neither is
  // rarer, and guessing it wrong publishes a plausible-looking site covering the wrong
  // thing. So it is asked, and the build refuses to publish without it.
  //
  // config keys — `mode` is REQUIRED, the rest optional:
  //   mode        — "repo" (this repo's own page) or "fleet" (the overview); no default
  //   canonRepo   — the reference member mounts are compared against (fleet view)
  //   rosterUrl   — a roster artifact; more than one member makes the fleet the landing view
  //   repos       — an inline roster instead of a URL
  //   clientId    — GitHub App / OAuth App client id, for the sign-in button
  //   exchangeUrl — the code-to-token endpoint that sign-in needs
  //   owner       — whose repos the fleet view enumerates (defaults to this repo's owner)
  //   exclude     — repos it keeps out (defaults to none)
  questions: [
    {
      id: 'mode',
      prompt: 'Is this deployment this repo\'s OWN dashboard, or the fleet overview across many repos? A fleet deployment also needs to name where its members come from — an "owner" whose repos are enumerated in the browser as the viewer (the one to prefer), or an explicit "repos" list or roster artifact.',
      distill: 'set config.mode to "repo" or "fleet" — there is no default and the build refuses to publish without it; a "fleet" answer must come with a roster source (owner/repos/rosterUrl), and a "repo" answer with none',
    },
  ],

  // The one step adoption CANNOT take, stated where the install flow can print it and
  // the adopting session can file it. Enabling Pages is a repository setting, and
  // `actions/configure-pages`' own `enablement` input cannot do it with the Action's
  // `GITHUB_TOKEN` — it needs a PAT with `repo`, or an app with `administration:write`.
  // Holding a credential that wide, in every member, to save one click is a far worse
  // trade than naming the click. So it is named.
  //
  // In a README this would be met after the first deploy had already failed; here it
  // arrives at the moment someone is present and the pack is new.
  adoptionHandover: [
    {
      step: 'Enable GitHub Pages on this repo with source "GitHub Actions" (Settings → Pages).',
      breaks: 'the deploy job fails on every run; the build still succeeds, so nothing else is affected',
      done: 'the Pages URL serves the dashboard, and the Claudinite dashboard workflow is green',
    },
    // ONE entry, not the four mechanical steps, because for many deployments the right
    // answer is "nothing" — a member's own dashboard read with a pasted token is on the
    // same 5,000/hour as a signed-in one. What every adopter does have to meet is the
    // DECISION, since until someone makes it their page reads GitHub anonymously; four
    // unconditional checkboxes that are mostly no-ops teach the reader to skim exactly
    // the list that exists to stop them skimming. The mechanics live in the README,
    // where they are read at the moment the answer is yes.
    {
      step: 'Decide how this dashboard authenticates its viewers: leave it on the pasted-token box (nothing to do), '
        + 'or give it a Sign in button — register a GitHub App with read-only Contents, Issues and Actions, install it on '
        + 'the account holding these repos, deploy the pack\'s oauth-exchange example, and set `clientId` and `exchangeUrl` '
        + 'on this pack\'s declaration. See "Who has to register the app" in the pack README: one App serves every '
        + 'deployment you own, and none can be inherited from another owner.',
      breaks: 'nothing fails, but a viewer who has not pasted a token reads GitHub anonymously at 60 requests/hour per IP — '
        + 'which one fleet sweep exceeds, so the page serves cached data or empty rows until the hour rolls',
      done: 'a signed-in viewer sees the rate pill read “…/5000 · user”, or this repo has recorded that the token box is '
        + 'this deployment\'s answer',
    },
  ],

  // Seeded, never converged: `.github/workflows/` cannot be written by the nightly, so
  // this arrives once, at adoption, and the repo owns it from there. It is a thin shim
  // over `build-site.mjs` in the mount for exactly that reason — the part that cannot
  // be updated is kept as small as possible.
  seedOps: [
    {
      template: 'stubs/workflows/claudinite-dashboard-pages.yml',
      dest: '.github/workflows/claudinite-dashboard-pages.yml',
    },
  ],
};

content.content:
1	// What the fleet DID — the counterpart to every other derivation here, which answers
2	// where to look. Pure: no clock, no I/O, no DOM.
3	//
4	// The page's panels are all fault-finding, and fault-finding has a blind spot: after
5	// a good week every count is zero, so a healthy fleet and a dead one render
6	// identically. Nothing on the page can tell them apart, because "nothing is wrong" and
7	// "nothing happened" are the same picture. This module is the other reading — closed
8	// work, scheduler runs, and which members moved at all — over a window of days.
9	//
10	// EVERY NUMBER COMES FROM A READ THE PAGE ALREADY MAKES. A per-member call to get a
11	// commit count would undo the budget work the whole client is built around, so the
12	// inputs are exactly the fleet loader's existing per-member reads: the first page of
13	// issues, the recent Actions runs, and the head commit whose date arrives with the sha
14	// the content cache is keyed by. Nothing here adds a request.
15	//
16	// WHAT THAT COSTS IS DEPTH, AND DEPTH IS DECLARED. One issue page is the most recent
17	// hundred issues by creation, and one runs page is the most recent thirty runs — so a
18	// day at the far end of the window is under-read rather than empty, and every series
19	// carries the horizon past which it stops being a count and starts being a floor.
20	
21	import { isParked, outcomeOf } from '../claudinite-tasks/shared-code/work-items.mjs';
22	import { isWorkItem } from './model.mjs';
23	
24	export const DAY_MS = 86400e3;
25	
26	const ms = (t) => (t == null ? null : new Date(t).getTime());
27	
28	// A UTC day. The queue's anchors and GitHub's timestamps are
29	// all UTC, so a local-time bucketing would put a member's midnight run on the wrong
30	// day depending on who is looking.
31	export const dayKey = (t) => new Date(t).toISOString().slice(0, 10);
32	
33	// The window's days, oldest first, including today. Built from keys rather than from
34	// arithmetic on a rendered date so a DST-free UTC ladder is the only thing anyone has
35	// to trust.
36	export function dayLadder(now, days) {
37	  const start = Math.floor(now / DAY_MS) * DAY_MS - (days - 1) * DAY_MS;
38	  return Array.from({ length: days }, (_, i) => dayKey(start + i * DAY_MS));
39	}
40	
41	// --- the daily series -----------------------------------------------------------
42	
43	// Work closed, runs finished and members moving, per day. `reads` is the fleet
44	// loader's raw per-member reads; a member that could not be read contributes nothing
45	// and is counted as unread rather than as a quiet day.
46	export function activitySeries(reads, { now, days = 14 } = {}) {
47	  const ladder = dayLadder(now, days);
48	  const index = new Map(ladder.map((d, i) => [d, i]));
49	  const blank = () => ladder.map((day) => ({
50	    day,
51	    work: { done: 0, delivered: 0, obsolete: 0, none: 0 },
52	    workClosed: 0,
53	    otherClosed: 0,
54	    runs: { success: 0, failure: 0, other: 0 },
55	    movers: new Set(),
56	  }));
57	
58	  const series = blank();
59	  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);
60	  // The oldest thing each read could see. A day before this is under-read for that
61	  // member — not quiet — and the series says so rather than drawing a confident zero.
62	  let issueHorizon = null;
63	  let runHorizon = null;
64	  const seen = (at, keep) => {
65	    const t = ms(at);
66	    if (t == null) return keep;
67	    return keep == null ? t : Math.max(keep, t);
68	  };
69	
70	  for (const read of readable) {
71	    const items = read.items ?? [];
72	    let oldestIssue = null;
73	    for (const i of items) {
74	      const created = ms(i.created_at);
75	      if (created != null) oldestIssue = oldestIssue == null ? created : Math.min(oldestIssue, created);
76	      if (i.state !== 'closed') continue;
77	      const at = ms(i.closed_at) ?? ms(i.updated_at);
78	      const slot = at == null ? undefined : index.get(dayKey(at));
79	      if (slot === undefined) continue;
80	      series[slot].movers.add(read.repo);
81	      if (isWorkItem(i)) {
82	        series[slot].workClosed += 1;
83	        series[slot].work[outcomeOf(i) ?? 'none'] += 1;
84	      } else {
85	        series[slot].otherClosed += 1;
86	      }
87	    }
88	    // A member whose page-1 window does not reach the start of the ladder truncates
89	    // the series for everyone, so the horizon is the LATEST such floor across members.
90	    if (!read.itemsComplete && oldestIssue != null) issueHorizon = seen(oldestIssue, issueHorizon);
91	
92	    let oldestRun = null;
93	    for (const r of read.runs ?? []) {
94	      const at = ms(r.created_at);
95	      if (at == null) continue;
96	      oldestRun = oldestRun == null ? at : Math.min(oldestRun, at);
97	      const slot = index.get(dayKey(at));
98	      if (slot === undefined) continue;
99	      series[slot].movers.add(read.repo);
100	      const bucket = r.status !== 'completed' ? 'other'
101	        : r.conclusion === 'success' ? 'success'
102	          : (r.conclusion === 'failure' || r.conclusion === 'timed_out' || r.conclusion === 'startup_failure') ? 'failure'
103	            : 'other';
104	      series[slot].runs[bucket] += 1;
105	    }
106	    if (oldestRun != null) runHorizon = seen(oldestRun, runHorizon);
107	
108	    // The default branch's tip. One date, so it marks the day that member last
109	    // landed something — not a commit count, and never drawn as one.
110	    const tip = ms(read.head?.committedAt);
111	    const tipSlot = tip == null ? undefined : index.get(dayKey(tip));
112	    if (tipSlot !== undefined) series[tipSlot].movers.add(read.repo);
113	  }
114	
115	  const rows = series.map((d) => ({ ...d, movers: [...d.movers].sort(), moved: d.movers.size }));
116	  const movedInWindow = new Set(rows.flatMap((d) => d.movers));
117	
118	  return {
119	    days: rows,
120	    from: ladder[0],
121	    to: ladder[ladder.length - 1],
122	    members: readable.length,
123	    unread: (reads ?? []).filter((r) => r?.error).length,
124	    moved: [...movedInWindow].sort(),
125	    quiet: readable.map((r) => r.repo).filter((r) => !movedInWindow.has(r)).sort(),
126	    totals: {
127	      workClosed: rows.reduce((n, d) => n + d.workClosed, 0),
128	      otherClosed: rows.reduce((n, d) => n + d.otherClosed, 0),
129	      runs: rows.reduce((n, d) => n + d.runs.success + d.runs.failure + d.runs.other, 0),
130	      runsFailed: rows.reduce((n, d) => n + d.runs.failure, 0),
131	    },
132	    // The day before which the series is a floor rather than a count, per source. Null
133	    // means every read reached past the window and the whole ladder is a real count.
134	    horizon: {
135	      issues: issueHorizon != null && issueHorizon > now - days * DAY_MS ? dayKey(issueHorizon) : null,
136	      runs: runHorizon != null && runHorizon > now - days * DAY_MS ? dayKey(runHorizon) : null,
137	    },
138	  };
139	}
140	
141	// --- what the machinery bought --------------------------------------------------
142	
143	// The window's work, and the same window before it. Two rules shape what may appear
144	// here, and both are the owner's:
145	//
146	//   NO VANITY TOTAL. Every figure is bounded by a window, because a number that only
147	//   grows says nothing about today. The comparison is against the preceding window of
148	//   the same length, so "more than last week" is a fact and not a feeling.
149	//
150	//   NOTHING INVENTED. No estimated hours, no saved-effort multiplier, no score. Each
151	//   figure is a count of things that are individually true and individually clickable.
152	//   A quantity nothing on this page measures does not get a tile with a guess in it.
153	export function fleetBenefits(reads, { now, windowDays = 7 } = {}) {
154	  const span = windowDays * DAY_MS;
155	  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);
156	
157	  const inWindow = (t, from, to) => t != null && t >= from && t < to;
158	
159	  const window = (from, to) => {
160	    let completed = 0;
161	    let unattended = 0;
162	    let parked = 0;
163	    let runs = 0;
164	    let runsFailed = 0;
165	    const members = new Set();
166	
167	    for (const read of readable) {
168	      for (const i of (read.items ?? []).filter(isWorkItem)) {
169	        // Decoded, never a literal label test: a member's items wear whatever
170	        // spelling the engine that filed them wrote (work-item's `statusOf`).
171	        const wasParked = isParked(i);
172	        // An item that needed a person is counted whether or not it has closed —
173	        // being parked IS the event, and the ones still sitting there are the whole
174	        // point. `updated_at` is when its label was last written, which is the
175	        // closest thing the queue leaves to "when it was handed over".
176	        if (wasParked && inWindow(ms(i.updated_at), from, to)) parked += 1;
177	
178	        if (i.state !== 'closed') continue;
179	        const at = ms(i.closed_at) ?? ms(i.updated_at);
180	        if (!inWindow(at, from, to)) continue;
181	        const outcome = outcomeOf(i);
182	        if (outcome === 'done' || outcome === 'delivered') {
183	          completed += 1;
184	          members.add(read.repo);
185	          // The parked label is the record of a human being pulled in: the queue puts
186	          // it on when a run cannot finish itself, and takes it off only when the item
187	          // is re-queued by hand. An item that closed without wearing it therefore ran
188	          // start to finish with nobody in the loop AT THE POINT IT CLOSED — an item
189	          // triaged and re-queued earlier in its life counts here too, and the panel
190	          // says so rather than claiming more than the labels can carry.
191	          if (!wasParked) unattended += 1;
192	        }
193	      }
194	      for (const r of read.runs ?? []) {
195	        if (!inWindow(ms(r.created_at), from, to)) continue;
196	        if (r.status !== 'completed') continue;
197	        runs += 1;
198	        if (r.conclusion !== 'success' && r.conclusion !== 'skipped' && r.conclusion !== 'cancelled') runsFailed += 1;
199	      }
200	    }
201	    return { completed, unattended, parked, runs, runsFailed, members: members.size };
202	  };
203	
204	  const current = window(now - span, now + 1);
205	  const previous = window(now - 2 * span, now - span);
206	
207	  // NO `converged` FIGURE. It counted members whose declaration carried a converge
208	  // datetime inside the window, and #1252 deleted that datetime — it recorded the
209	  // last full re-vendor rather than the last converge, so the tile was already
210	  // counting the wrong thing. Nothing this sweep reads can answer "converged in the
211	  // last N days": a member's installed versions say WHAT it holds, never when it
212	  // took it. The panel names the gap instead of approximating it, which is the rule
213	  // this figure broke twice over (#1001, #1008).
214	  return {
215	    windowDays,
216	    current,
217	    previous,
218	    members: readable.length,
219	  };
220	}
221	
222	// A window-over-window change, in the only form that is honest when the previous
223	// window may itself be under-read: the delta, and which way it points.
224	export function delta(current, previous) {
225	  if (!Number.isFinite(current) || !Number.isFinite(previous)) return { dir: 'flat', by: 0 };
226	  const by = current - previous;
227	  return { dir: by > 0 ? 'up' : by < 0 ? 'down' : 'flat', by: Math.abs(by) };
228	}
229	
230	// --- one member's commit history -------------------------------------------------
231	
232	// The last N days of a member's commits, as a flat oldest-first ladder — the shape a
233	// GitHub-style square grid draws straight from.
234	//
235	// The input is `/stats/commit_activity`: 52 weeks, each a UTC-Sunday start and seven
236	// daily counts. This is the ONE read on the fleet page that is not derived from
237	// something already fetched, which is why it is priced as decoration everywhere it
238	// appears — and why its three empty answers must stay distinguishable. `null` is "not
239	// read" (withheld, or GitHub still computing the statistics) and is NOT the same fact
240	// as an array of zeroes, which is a repo that genuinely did nothing.
241	//
242	// A day the year does not cover is `null` rather than `0` for the same reason: a
243	// window wider than the data is under-read at its far end, not quiet there.
244	export function commitDays(weeks, { now, days = 90 } = {}) {
245	  if (!Array.isArray(weeks)) return null;
246	
247	  const byDay = new Map();
248	  for (const w of weeks) {
249	    const start = Number(w?.week);
250	    if (!Number.isFinite(start)) continue;
251	    (w.days ?? []).forEach((count, i) => {
252	      byDay.set(dayKey(start * 1000 + i * DAY_MS), Number(count) || 0);
253	    });
254	  }
255	
256	  const ladder = dayLadder(now, days);
257	  const rows = ladder.map((day) => ({ day, count: byDay.has(day) ? byDay.get(day) : null }));
258	  const counted = rows.filter((r) => r.count != null);
259	  return {
260	    days: rows,
261	    buckets: bucketWeekly(rows),
262	    total: counted.reduce((n, r) => n + r.count, 0),
263	    peak: counted.reduce((n, r) => Math.max(n, r.count), 0),
264	    // Days inside the window the year of statistics did not reach. Stated rather than
265	    // drawn as blank squares that read as quiet ones.
266	    unread: rows.length - counted.length,
267	  };
268	}
269	
270	// The same window in weeks, which is the resolution a QUARTER of history is legible
271	// at. Drawn daily, an ordinary repo's weekend is a trough and a Tuesday a spike, so a
272	// 90-point curve across a column is a sawtooth that hides the only thing the column is
273	// for: whether this repo is being worked on, and whether it always was.
274	//
275	// The daily counts are kept — they are the total, the peak and the hover — and only
276	// the drawn line is smoothed. Weeks run back from today, so the OLDEST bucket is the
277	// short one, and a week is null only when every day in it was unread; a week that was
278	// partly read is a real sum over what there was.
279	const WEEK = 7;
