282	  const out = [];
283	  for (let end = rows.length; end > 0; end -= WEEK) {
284	    const slice = rows.slice(Math.max(0, end - WEEK), end);
285	    const read = slice.filter((r) => r.count != null);
286	    out.unshift({
287	      from: slice[0].day,
288	      to: slice[slice.length - 1].day,
289	      days: slice.length,
290	      count: read.length ? read.reduce((n, r) => n + r.count, 0) : null,
291	    });
292	  }
