1	// Assemble the publishable site from the mount.
2	//
3	// Lives in the pack rather than in the member, and is read out of `.claudinite/shared/`
4	// by the seeded workflow — the same shape as the scheduler stub reading the engine's
5	// scheduler run. So the assembly logic keeps converging with the canon while only the workflow,
6	// the file that cannot converge, is frozen at adoption.
7	//
8	// Run from the member's root:
9	//   node .claudinite/shared/packs/claudinite-dashboard/build-site.mjs [--out _site]
10	//
11	// Reads its deployment settings from the member's own declaration — the
12	// `claudinite-dashboard` entry's `config` — so there is no second place to configure
13	// the same thing and nothing to keep in step. Every key is optional.
14	//
15	// INERT RATHER THAN FAILING. A repo whose mount does not yet carry this pack's page
16	// (adopted, not yet converged) exits clean having produced nothing. That is an ordinary
17	// state on a fleet, not a fault, and failing on it would paint every run red until the
18	// converge caught up.
19	
20	import { cp, mkdir, writeFile, readFile, rm, access } from 'node:fs/promises';
21	import { join, dirname, resolve } from 'node:path';
22	import { fileURLToPath } from 'node:url';
23	import { resolveMode } from './config.mjs';
24	import { settingsPath } from '../../engine/settings-file.mjs';
25	
26	const HERE = dirname(fileURLToPath(import.meta.url));
27	
28	// The page imports the queue's own modules by relative path — the tasks pack's published
29	// `shared-code/`, and the engine surface beneath it — precisely so it cannot drift from
30	// them. The published tree therefore has to preserve that shape: flattening the dashboard
31	// to the site root sends those imports above the root and the page does not boot. So every
32	// directory it reaches is staged at the depth it already has, and the site root is a redirect.
33	const HOME = 'packs/claudinite-dashboard';
34	const ENGINE = 'engine';
35	const TASKS = 'packs/claudinite-tasks';
36	
37	// Local-only or explanatory files. None belong on a published site — `serve.mjs` least
38	// of all, being a file server's source sitting where it reads as part of the page.
39	const NOT_PUBLISHED = ['serve.mjs', 'build-site.mjs', 'pack.mjs', 'oauth-exchange.example.mjs',
40	  'dashboard.config.example.json', 'README.md', 'badge.svg', 'stubs'];
41	
42	const exists = async (p) => { try { await access(p); return true; } catch { return false; } };
43	
44	const arg = (name, fallback) => {
45	  const i = process.argv.indexOf(`--${name}`);
46	  return i === -1 ? fallback : process.argv[i + 1];
47	};
48	
49	// The mount this pack was read from, and the repo root above it. Resolved from this
50	// file's own location rather than from `process.cwd()`, so the script works wherever it
51	// is invoked from.
52	const mountRoot = resolve(HERE, '../..');            // .claudinite/shared  (or the canon root)
53	const repoRoot = resolve(arg('root', process.cwd()));
54	const OUT = resolve(repoRoot, arg('out', '_site'));
55	
56	// This script ships inside the page's own directory, so that directory is `HERE` —
57	// no path guessing, and it stays right if the pack is ever renamed.
58	const pageSource = HERE;
59	const engineSource = join(mountRoot, ENGINE);
60	const tasksSource = join(mountRoot, TASKS);
61	
62	if (!await exists(join(pageSource, 'index.html')) || !await exists(engineSource)) {
63	  process.stdout.write(
64	    `No dashboard in the mount at ${pageSource} — nothing to publish. `
65	    + 'The next converge that delivers this pack will make this build produce a site.\n',
66	  );
67	  process.exit(0);
68	}
69	
70	// --- settings, from the member's own declaration ---------------------------------
71	
72	async function declaration() {
73	  try {
74	    return JSON.parse(await readFile(settingsPath(repoRoot), 'utf8'));
75	  } catch {
76	    return null;
77	  }
78	}
79	
80	const decl = await declaration();
81	const entry = (decl?.packs ?? []).find((p) => (typeof p === 'string' ? p : p?.id) === 'claudinite-dashboard');
82	const cfg = (typeof entry === 'object' && entry?.config) || {};
83	
84	// --- stage ------------------------------------------------------------------------
85	
86	await rm(OUT, { recursive: true, force: true });
87	await mkdir(join(OUT, HOME), { recursive: true });
88	
89	await cp(pageSource, join(OUT, HOME), { recursive: true });
90	// The whole engine tree rather than a hand-picked subset: the page's import graph is
91	// the engine's business and may grow a module, and a curated copy would break silently
92	// the first time it did. It discloses nothing — the mount is already committed in this
93	// repo, so every byte is as public as the repo is.
94	await cp(engineSource, join(OUT, ENGINE), { recursive: true });
95	// The queue modules the page reads, at the same depth, for the same reason.
96	if (await exists(tasksSource)) await cp(tasksSource, join(OUT, TASKS), { recursive: true });
97	
98	for (const f of NOT_PUBLISHED) await rm(join(OUT, HOME, f), { recursive: true, force: true });
99	
100	await writeFile(join(OUT, 'index.html'), `<!doctype html>
101	<html lang="en">
102	<head>
103	<meta charset="utf-8">
104	<title>Claudinite tasks</title>
105	<link rel="icon" href="./${HOME}/favicon.svg" type="image/svg+xml">
106	<meta http-equiv="refresh" content="0; url=./${HOME}/">
107	<link rel="canonical" href="./${HOME}/">
108	</head>
109	<body><p>Continue to the <a href="./${HOME}/">task dashboard</a>.</p></body>
110	</html>
111	`);
112	
113	// Pages runs uploaded artifacts through Jekyll unless told otherwise, and Jekyll drops
114	// files and directories beginning with an underscore.
115	await writeFile(join(OUT, '.nojekyll'), '');
116	
117	// --- the roster --------------------------------------------------------------------
118	
119	// WHICH DASHBOARD THIS DEPLOYMENT IS, and it is decided by SHAPE rather than by a mode
120	// switch: a declaration that says where more than one member comes from builds the
121	// fleet dashboard, and anything else builds this repo's own. So there is nothing to ask
122	// at adoption, nothing to keep in step, and no way to configure a roster and still get
123	// the wrong landing page.
124	//
125	// Three ways to say where the members come from, in precedence order:
126	//   repos      — an explicit list, for a deployment that wants a fixed set;
127	//   rosterFile — a generated artifact in this repo (the legacy shape);
128	//   owner      — enumerate that owner's repos IN THE BROWSER, as the viewer.
129	//
130	// The third is the one to use. It stores no repo list anywhere, and it means the fleet
131	// a person sees is exactly the fleet they can read — a member outside their access is
132	// not in it, rather than being in it as a row they cannot open.
133	let repos = Array.isArray(cfg.repos) ? cfg.repos.filter((r) => /^[^/\s]+\/[^/\s]+$/.test(r)) : [];
134	let rosterUrl = null;
135	
136	if (!repos.length && cfg.rosterFile) {
137	  try {
138	    const doc = JSON.parse(await readFile(join(repoRoot, cfg.rosterFile), 'utf8'));
139	    const names = Array.isArray(doc) ? doc
140	      : Array.isArray(doc?.repos) ? doc.repos
141	        : doc?.repos && typeof doc.repos === 'object' ? Object.keys(doc.repos) : [];
142	    repos = names.filter((r) => typeof r === 'string' && /^[^/\s]+\/[^/\s]+$/.test(r)).sort();
143	  } catch {
144	    // A roster the member named but this cannot read is worth saying out loud: the site
145	    // would otherwise publish as a single-repo dashboard and look intentional.
146	    process.stdout.write(`WARNING: rosterFile ${cfg.rosterFile} could not be read — the site will cover only this repo.\n`);
147	  }
148	}
149	if (repos.length) {
150	  rosterUrl = './fleet-roster.GENERATED.json';
151	  // Only the names travel: a fleet artifact is usually a large statistics file the
152	  // dashboard never reads, and a page should not download it to fill a dropdown.
153	  await writeFile(join(OUT, HOME, 'fleet-roster.GENERATED.json'), `${JSON.stringify({ repos }, null, 2)}\n`);
154	} else if (cfg.rosterUrl) {
155	  rosterUrl = cfg.rosterUrl;
156	}
157	
158	// --- the config the page reads -------------------------------------------------------
159	
160	const repoSlug = process.env.GITHUB_REPOSITORY ?? null;
161	// Which dashboard this is — STATED by the declaration, and refused when it is not. The
162	// judgment is resolveMode's alone so the build and the page cannot drift apart; what is
163	// added here is that the build reads the roster off `rosterFile` too, and by this point
164	// has already resolved it into `repos`.
165	let fleetMode;
166	try {
167	  fleetMode = resolveMode({ ...cfg, rosterUrl: rosterUrl ?? cfg.rosterUrl }) === 'fleet';
168	} catch (e) {
169	  process.stderr.write(`claudinite-dashboard: ${e.message}\n`);
170	  process.exit(1);
171	}
172	const config = {
173	  mode: fleetMode ? 'fleet' : 'repo',
174	  clientId: cfg.clientId ?? null,
175	  exchangeUrl: cfg.exchangeUrl ?? null,
176	  redirectUri: cfg.redirectUri ?? null,
177	  canonRepo: cfg.canonRepo ?? null,
178	  // Whose repos a fleet deployment covers, enumerated in the browser as the viewer, and
179	  // which of them are not members. Both travel through as they stand: this build has no
180	  // credential to enumerate with, and would be the wrong place to try — a list resolved
181	  // here would be the same list for every viewer.
182	  owner: cfg.owner ?? null,
183	  exclude: Array.isArray(cfg.exclude) ? cfg.exclude : [],
184	  rosterUrl,
185	  repos: [],
186	  // In fleet mode the overview is the landing view, so nothing is preselected; in repo
187	  // mode there is exactly one repo to show and it is this one.
188	  defaultRepo: fleetMode ? null : (cfg.defaultRepo ?? repoSlug),
189	};
190	await writeFile(join(OUT, HOME, 'dashboard.config.json'), `${JSON.stringify(config, null, 2)}\n`);
191	
192	// Say which mode the site actually built in. Sign-in quietly not being configured, or a
193	// fleet roster quietly not arriving, are exactly the things nobody notices until they
194	// wonder why the page is asking for a token or showing one repo.
195	const signIn = config.clientId && config.exchangeUrl
196	  ? 'configured'
197	  : `NOT configured — the site will ask for a token${config.clientId ? ' (exchangeUrl missing)' : ''}${config.exchangeUrl ? ' (clientId missing)' : ''}`;
198	const covers = repos.length ? `${repos.length} named members`
199	  : cfg.owner ? `every repo under ${cfg.owner} the viewer can read${config.exclude.length ? `, less ${config.exclude.length} excluded` : ''}`
200	    : rosterUrl ? `whatever ${rosterUrl} names`
201	      : `this repo${config.defaultRepo ? ` (${config.defaultRepo})` : ''}`;
202	process.stdout.write(
203	  `Built ${OUT}\n`
204	  + `  mode: ${fleetMode ? 'fleet-dashboard' : 'repo-dashboard'} (declared)\n`
205	  + `  covers: ${covers}\n`
206	  + `  canon reference: ${config.canonRepo ?? 'not set — member mount freshness reads unknown'}\n`
207	  + `  sign-in: ${signIn}\n`,
208	);
209

